<template>
    <CRow>
        <CCol col="12" xl="10">
            <CCard>
                <CCardHeader>
                    Edición Publicación
                </CCardHeader>
                <CCardBody>
                    <CRow>
                        <CCol sm="12">
                            <CInput
                                label="Titulo"
                                placeholder="Titulo"
                                v-model="titulo"
                            />
                        </CCol>
                    </CRow>
                    <CRow>
                        <CCol sm="12">
                            <CInput
                                label="Slug"
                                placeholder="Slug"
                                v-model="slug"
                            />
                        </CCol>
                    </CRow>
                    <CRow>
                        <CCol sm="12">
                            <CInput
                                label="Imagen"
                                placeholder="imagen"
                                v-model="image"
                            />
                        </CCol>
                    </CRow>
                    <CRow>

                        <CCol sm="12">
                            <label>Body</label>
                            <CTextarea
                                rows="20"
                                col="20"
                                v-model="content"

                            />
                        </CCol>
                    </CRow>
                    <CRow>

                        <CCol sm="12">
                            <label>Meta Description</label>
                            <CTextarea
                                rows="5"
                                col="20"
                                v-model="meta_descripcion"

                            />
                        </CCol>
                    </CRow>
                    <CRow>
                        <CCol sm="12">

                            <CButton
                                color="success"
                                size=""
                                class="m-2"
                                @click="guardarPost"
                            >Guardar</CButton>
                            <CButton
                                color="dangre"
                                size=""
                                class="m-2"
                                @click="regresar"
                            >Regresar</CButton>
                        </CCol>
                    </CRow>
                </CCardBody>
            </CCard>
        </CCol>
    </CRow>
</template>

<script>


    const axios = require('axios').default;
    export default {
        name: "Postedit",
        components: {

        },
        data(){
            return {
                editorOption: {
                    // Some Quill options...
                },
                mensaje:'Publicación guardada',
                mostrar: false,
                id: '',
                content: '',
                titulo: '',
                slug: '',
                image:'',
                meta_descripcion: ''
            }
        },
        methods: {
            alertDisplay() {

                this.$swal('Exito','Publicación guardada!','success');
            },

            guardarPost() {

                let token_id = localStorage.getItem('id_token');
                axios.post('/back/post/edit',{
                    token: token_id,
                    id: this.id,
                    title: this.titulo,
                    slug: this.slug,
                    body: this.content,
                    image: this.image,
                    meta_description: this.meta_descripcion

                }).then(response => {
                    //this.$swal('Mensaje', 'Publicación Guardada', 'success');
                    this.alertDisplay();
                }, response => {   })
            },
            regresar(){
                this.$router.push({
                    name: 'Posts'
                })
            }
        },
        computed: {

        },
        mounted() {
            this.$nextTick(() => {
                let token_id = localStorage.getItem('id_token');
                axios.post('/back/post',{
                    token: token_id,
                    id: this.$route.params.id
                }).then(response => {
                    this.id = response.data.id;
                    this.titulo = response.data.title;
                    this.slug = response.data.slug;
                    this.image = response.data.image;
                    this.content = response.data.body;
                    this.meta_descripcion = response.data['meta-description'];
                }, response => {   })
            })

        }
    }
</script>

